//! Replays the TypeScript-generated transition vectors (`transition_vectors.json`,
//! regenerated by `generateTransitionVectors.mjs`) against the Rust policies.
use serde_json::{Value, json};

use super::{PROTOCOL, activity, indicators, timeline, window};

fn vectors() -> Value {
    serde_json::from_str(include_str!("transition_vectors.json"))
        .expect("committed vectors are valid JSON")
}

fn cases(v: &Value, key: &str) -> Vec<Value> {
    let list = v[key].as_array().expect("vector group").clone();
    assert!(!list.is_empty(), "{key}");
    list
}

fn run(f: fn(&str) -> Result<String, String>, input: &Value) -> Value {
    serde_json::from_str(&f(&input.to_string()).expect("valid input")).expect("JSON output")
}

#[test]
fn window_matches_typescript() {
    let v = vectors();
    for c in cases(&v, "prune") {
        assert_eq!(
            run(window::prune_json, &c["input"]),
            c["out"],
            "{}",
            c["name"]
        );
    }
    for c in cases(&v, "preserve") {
        assert_eq!(
            run(window::preserve_json, &c["input"]),
            c["out"],
            "{}",
            c["name"]
        );
    }
}

#[test]
fn timeline_matches_typescript() {
    let v = vectors();
    for c in cases(&v, "merge") {
        assert_eq!(
            run(timeline::merge_json, &c["input"]),
            c["out"],
            "{}",
            c["name"]
        );
    }
    for c in cases(&v, "timeline") {
        let name = &c["name"];
        let base = json!({"entries": c["entries"], "bookmarks": c["bookmarks"]});
        assert_eq!(
            run(timeline::exchange_index_json, &base),
            c["index"],
            "{name}"
        );
        let id = json!({"entries": c["entries"], "id": c["id"]});
        assert_eq!(
            run(timeline::response_id_json, &id),
            c["response"],
            "{name}"
        );
        // `undecryptable` is a page-side flag; the vectors carry rows with content.
        let pair = json!({"entries": c["entries"], "id": c["id"], "pendingUserId": c["pendingUserId"], "undecryptable": false});
        assert_eq!(run(timeline::pair_json, &pair), c["pair"], "{name}");
    }
}

#[test]
fn activity_matches_typescript() {
    let v = vectors();
    for c in cases(&v, "activity") {
        assert_eq!(
            run(activity::ancestors_json, &c["input"]),
            c["ancestors"],
            "{}",
            c["name"]
        );
        assert_eq!(
            run(activity::aggregate_json, &c["input"]),
            c["aggregate"],
            "{}",
            c["name"]
        );
    }
}

#[test]
fn indicators_match_typescript() {
    let v = vectors();
    for c in cases(&v, "composer") {
        assert_eq!(
            run(indicators::composer_json, &c["input"]),
            c["out"],
            "{}",
            c["name"]
        );
    }
    for c in cases(&v, "title") {
        assert_eq!(
            run(indicators::title_json, &c["input"]),
            c["out"],
            "{}",
            c["name"]
        );
    }
}

#[test]
fn undecryptable_user_row_is_reported() {
    let input = json!({"entries": [{"id": "u", "role": "user", "userMessageId": null}], "id": "u", "pendingUserId": null, "undecryptable": true});
    assert_eq!(
        run(timeline::pair_json, &input),
        json!({"error": "undecryptable"})
    );
}

#[test]
fn malformed_input_is_refused_with_the_protocol_code() {
    let fns: [fn(&str) -> Result<String, String>; 10] = [
        window::prune_json,
        window::preserve_json,
        timeline::merge_json,
        timeline::exchange_index_json,
        timeline::response_id_json,
        timeline::pair_json,
        activity::ancestors_json,
        activity::aggregate_json,
        indicators::composer_json,
        indicators::title_json,
    ];
    for f in fns {
        for bad in [
            "not json",
            "{}",
            "[]",
            "null",
            r#"{"messages": 5, "entries": "x", "chats": 1}"#,
        ] {
            assert_eq!(f(bad), Err(PROTOCOL.to_string()), "{bad}");
        }
    }
}
